// This parser is deliberately independent of Fingerprinter: comparing the
// captured browser bytes against generated bytes must not hide a parser bug.
// Only extension permutation, GREASE codepoints, ephemeral public keys, and
// GREASE ECH randomness are normalized. Ordered capability lists and trust
// anchor IDs retain their original order and bytes.
type chrome158WireHello struct {
	Version            uint16
	RandomLength       int
	SessionIDLength    int
	CipherSuites       []uint16
	CompressionMethods []byte
	Extensions         map[uint16][]string
}

type chrome158Reader struct {
	t     *testing.T
	b     []byte
	label string
}

func (r *chrome158Reader) take(n int) []byte {
	r.t.Helper()
	if n < 0 || n > len(r.b) {
		r.t.Fatalf("%s: truncated field: need %d bytes, have %d", r.label, n, len(r.b))
	}
	b := r.b[:n]
	r.b = r.b[n:]
	return b
}

func (r *chrome158Reader) number(n int) int {
	r.t.Helper()
	v := 0
	for _, b := range r.take(n) {
		v = v<<8 | int(b)
	}
	return v
}

func (r *chrome158Reader) vector(n int) []byte {
	r.t.Helper()
	return r.take(r.number(n))
}

func (r *chrome158Reader) end() {
	r.t.Helper()
	if len(r.b) != 0 {
		r.t.Fatalf("%s: %d trailing bytes", r.label, len(r.b))
	}
}

func chrome158NormalizeGREASE(v uint16) uint16 {
	if isGREASEUint16(v) {
		return GREASE_PLACEHOLDER
	}
	return v
}

func chrome158Uint16s(t *testing.T, b []byte) []uint16 {
	t.Helper()
	if len(b)%2 != 0 {
		t.Fatalf("odd uint16 vector length: %d", len(b))
	}
	out := make([]uint16, len(b)/2)
	for i := range out {
		out[i] = chrome158NormalizeGREASE(uint16(b[2*i])<<8 | uint16(b[2*i+1]))
	}
	return out
}

func chrome158NormalizeExtension(t *testing.T, id uint16, body []byte) string {
	t.Helper()
	r := chrome158Reader{t, body, fmt.Sprintf("extension %#04x", id)}
	var value string
	switch id {
	case 10, 13: // supported_groups, signature_algorithms
		value = fmt.Sprint(chrome158Uint16s(t, r.vector(2)))
	case 43: // supported_versions
		value = fmt.Sprint(chrome158Uint16s(t, r.vector(1)))
	case 51: // key_share
		shares := chrome158Reader{t, r.vector(2), "key_share entries"}
		var entries []string
		for len(shares.b) > 0 {
			group := uint16(shares.number(2))
			key := shares.vector(2)
			entry := fmt.Sprintf("%04x/%d", chrome158NormalizeGREASE(group), len(key))
			if isGREASEUint16(group) {
				entry += "/" + hex.EncodeToString(key)
			}
			entries = append(entries, entry)
		}
		value = strings.Join(entries, ",")
	case 0xfe0d: // GREASE encrypted_client_hello
		outer, kdf, aead := r.number(1), r.number(2), r.number(2)
		r.take(1) // randomized config_id
		enc, payload := r.vector(2), r.vector(2)
		if outer != 0 || !slices.Contains([]int{144, 176, 208, 240}, len(payload)) {
			t.Fatalf("unexpected GREASE ECH shape: outer=%d, payload length=%d", outer, len(payload))
		}
		value = fmt.Sprintf("%d/%d/%d/enc=%d/payload=144,176,208,240", outer, kdf, aead, len(enc))
	case 0xca34: // trust_anchors
		ids := chrome158Reader{t, r.vector(2), "trust anchor IDs"}
		for len(ids.b) > 0 {
			if len(ids.vector(1)) == 0 {
				t.Fatal("empty trust anchor ID in fixture")
			}
		}
		value = hex.EncodeToString(body)
	default:
		value = hex.EncodeToString(r.take(len(r.b)))
	}
	r.end()
	return value
}

func chrome158ParseWire(t *testing.T, data []byte) (chrome158WireHello, []uint16, map[uint16][]byte) {
	t.Helper()
	r := chrome158Reader{t, data, "ClientHello"}
	if len(data) > 0 && data[0] == byte(recordTypeHandshake) {
		if r.number(1) != int(recordTypeHandshake) || r.number(2) != int(VersionTLS10) {
			t.Fatal("unexpected ClientHello TLS record header")
		}
		record := r.vector(2)
		r.end()
		r = chrome158Reader{t, record, "ClientHello handshake"}
	}
	if r.number(1) != 1 {
		t.Fatal("fixture is not a ClientHello")
	}
	body := r.vector(3)
	r.end()
	r = chrome158Reader{t, body, "ClientHello body"}
	version := uint16(r.number(2))
	random := r.take(32)
	sid := r.vector(1)
	ciphers := chrome158Uint16s(t, r.vector(2))
	compression := bytes.Clone(r.vector(1))
	extensions := r.vector(2)
	r.end()
	out := chrome158WireHello{version, len(random), len(sid), ciphers, compression, make(map[uint16][]string)}
	r = chrome158Reader{t, extensions, "ClientHello extensions"}
	seen, raw := make(map[uint16]bool), make(map[uint16][]byte)
	var order []uint16
	for len(r.b) > 0 {
		id := uint16(r.number(2))
		body := r.vector(2)
		if seen[id] {
			t.Fatalf("duplicate extension %#04x", id)
		}
		seen[id] = true
		raw[id] = bytes.Clone(body)
		normalizedID := chrome158NormalizeGREASE(id)
		order = append(order, normalizedID)
		out.Extensions[normalizedID] = append(out.Extensions[normalizedID], chrome158NormalizeExtension(t, id, body))
	}
	for _, values := range out.Extensions {
		sort.Strings(values) // distinguish the two GREASE bodies independently of their values
	}
	return out, order, raw
}

func chrome158Fixture(t *testing.T) []byte {
	t.Helper()
	text, err := os.ReadFile("testdata/chrome158_clienthello.hex")
	if err != nil {
		t.Fatal(err)
	}
	data, err := hex.DecodeString(strings.Join(strings.Fields(string(text)), ""))
	if err != nil {
		t.Fatal(err)
	}
	return data
}

func chrome158FixtureServerName(t *testing.T, raw map[uint16][]byte) string {
	t.Helper()
	r := chrome158Reader{t, raw[0], "server_name"}
	names := chrome158Reader{t, r.vector(2), "server_name list"}
	r.end()
	if names.number(1) != 0 {
		t.Fatal("fixture SNI is not a host name")
	}
	name := string(names.vector(2))
	names.end()
	return name
}

func chrome158Build(t *testing.T, id ClientHelloID, serverName string, spec *ClientHelloSpec) *UConn {
	t.Helper()
	client := UClient(&net.TCPConn{}, &Config{ServerName: serverName, ClientSessionCache: nil}, id)
	if spec != nil {
		if err := client.ApplyPreset(spec); err != nil {
			t.Fatal(err)
		}
	}
	if err := client.BuildHandshakeState(); err != nil {
		t.Fatal(err)
	}
	return client
}

func chrome158CompareWire(t *testing.T, want, got chrome158WireHello) {
	t.Helper()
	if !reflect.DeepEqual(got, want) {
		t.Errorf("generated ClientHello differs from fresh Chrome 158 capture:\n got: %+v\nwant: %+v", got, want)
	}
}

func TestChrome158CapturedClientHello(t *testing.T) {
	if HelloChrome_Auto != HelloChrome_133 {
		t.Fatalf("HelloChrome_Auto = %s, want %s", HelloChrome_Auto.Str(), HelloChrome_133.Str())
	}
	want, _, captured := chrome158ParseWire(t, chrome158Fixture(t))
	client := chrome158Build(t, HelloChrome_158, chrome158FixtureServerName(t, captured), nil)
	got, _, generated := chrome158ParseWire(t, client.HandshakeState.Hello.Raw)
	chrome158CompareWire(t, want, got)
	if ticket, ok := generated[35]; !ok || len(ticket) != 0 {
		t.Fatal("fresh profile must advertise an empty session_ticket extension")
	}
	if _, ok := generated[41]; ok {
		t.Fatal("fresh profile unexpectedly offers pre_shared_key")
	}
}

func TestChrome158DefaultFingerprintRoundTrip(t *testing.T) {
	fixture := chrome158Fixture(t)
	want, wantOrder, raw := chrome158ParseWire(t, fixture)
	spec, err := (&Fingerprinter{}).FingerprintClientHello(fixture)
	if err != nil {
		t.Fatalf("default Fingerprinter must parse captured Chrome 158 ClientHello: %v", err)
	}
	client := chrome158Build(t, HelloCustom, chrome158FixtureServerName(t, raw), spec)
	got, gotOrder, _ := chrome158ParseWire(t, client.HandshakeState.Hello.Raw)
	chrome158CompareWire(t, want, got)
	if !slices.Equal(gotOrder, wantOrder) {
		t.Errorf("fingerprint roundtrip reordered extensions: got %x, want %x", gotOrder, wantOrder)
	}
	if chrome158TrustAnchors(t, spec.Extensions) == nil {
		t.Fatal("fingerprinted trust anchors must use the typed extension")
	}
}

func chrome158TrustAnchors(t *testing.T, extensions []TLSExtension) *TrustAnchorsExtension {
	t.Helper()
	for _, extension := range extensions {
		if anchors, ok := extension.(*TrustAnchorsExtension); ok {
			return anchors
		}
	}
	t.Fatal("missing typed trust_anchors extension")
	return nil
}

func TestChrome158PresetOwnership(t *testing.T) {
	spec, err := UTLSIdToSpec(HelloChrome_158)
	if err != nil {
		t.Fatal(err)
	}
	before := spec.clone()
	first := chrome158Build(t, HelloCustom, "example.com", &spec)
	second := chrome158Build(t, HelloCustom, "example.com", &spec)
	if !reflect.DeepEqual(&spec, before) {
		t.Fatal("ApplyPreset mutated the reusable Chrome 158 preset")
	}
	anchors := chrome158TrustAnchors(t, first.Extensions)
	if len(anchors.TrustAnchorIDs) == 0 || len(anchors.TrustAnchorIDs[0]) == 0 {
		t.Fatal("Chrome 158 capture must contain trust anchor IDs")
	}
	anchors.TrustAnchorIDs[0][0] ^= 0xff
	for _, extension := range first.Extensions {
		switch extension := extension.(type) {
		case *SignatureAlgorithmsExtension:
			extension.SupportedSignatureAlgorithms[0] = PKCS1WithSHA1
		case *SupportedCurvesExtension:
			extension.Curves[0] = CurveP384
		}
	}
	first.HandshakeState.Hello.CipherSuites[0] = TLS_RSA_WITH_AES_256_CBC_SHA
	if !reflect.DeepEqual(&spec, before) {
		t.Fatal("connection mutations leaked into the reusable Chrome 158 preset")
	}
	wantAnchors := chrome158TrustAnchors(t, before.Extensions).TrustAnchorIDs
	if !reflect.DeepEqual(chrome158TrustAnchors(t, second.Extensions).TrustAnchorIDs, wantAnchors) {
		t.Fatal("nested trust anchor mutations leaked between connections")
	}
	later, err := UTLSIdToSpec(HelloChrome_158)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(chrome158TrustAnchors(t, later.Extensions).TrustAnchorIDs, wantAnchors) {
		t.Fatal("trust anchor mutations leaked into future preset instances")
	}
}

func TestChrome158SignatureGREASESeed(t *testing.T) {
	client := UClient(&net.TCPConn{}, &Config{
		ServerName: "example.com",
		Rand:       bytes.NewReader(bytes.Repeat([]byte{0xa1}, 8192)),
	}, HelloChrome_158)
	if err := client.BuildHandshakeState(); err != nil {
		t.Fatal(err)
	}
	// BoringSSL reserves seed slot 7 for signature algorithms, independently
	// of the cipher, group, extension, and version GREASE slots.
	const signatureSeedSlot = 7
	seed := client.greaseSeed[signatureSeedSlot]
	want := (seed & 0xf0) | 0x0a
	want |= want << 8
	if want == GREASE_PLACEHOLDER {
		t.Fatal("deterministic test seed must distinguish generated GREASE from the placeholder")
	}
	_, _, raw := chrome158ParseWire(t, client.HandshakeState.Hello.Raw)
	r := chrome158Reader{t, raw[13], "signature_algorithms"}
	signatures := chrome158Reader{t, r.vector(2), "signature schemes"}
	r.end()
	got := uint16(signatures.number(2))
	if got != want || got == GREASE_PLACEHOLDER {
		t.Fatalf("signature GREASE = %#04x, want %#04x from BoringSSL seed slot 7", got, want)
	}
	if gotState := uint16(client.HandshakeState.Hello.SupportedSignatureAlgorithms[0]); gotState != want {
		t.Fatalf("signature GREASE in handshake state = %#04x, want %#04x", gotState, want)
	}
}

func TestChrome133CapabilitiesPreserved(t *testing.T) {
	client := chrome158Build(t, HelloChrome_133, "example.com", nil)
	_, _, raw := chrome158ParseWire(t, client.HandshakeState.Hello.Raw)
	r := chrome158Reader{t, raw[13], "Chrome 133 signature_algorithms"}
	got := chrome158Uint16s(t, r.vector(2))
	r.end()
	want := []uint16{
		uint16(ECDSAWithP256AndSHA256), uint16(PSSWithSHA256), uint16(PKCS1WithSHA256),
		uint16(ECDSAWithP384AndSHA384), uint16(PSSWithSHA384), uint16(PKCS1WithSHA384),
		uint16(PSSWithSHA512), uint16(PKCS1WithSHA512),
	}
	if !slices.Equal(got, want) {
		t.Fatalf("Chrome 133 signature schemes changed: got %x, want original classical schemes %x", got, want)
	}
	if _, ok := raw[0xca34]; ok {
		t.Fatal("Chrome 158 trust anchor IDs leaked into the Chrome 133 profile")
	}
}

func TestServerPaddingRequest(t *testing.T) {
	ext := &FakeServerPaddingExtension{}
	for _, body := range [][]byte{nil, {0}, {0, 1, 2}} {
		if _, err := ext.Write(body); err == nil {
			t.Fatalf("accepted malformed server padding request %x", body)
		}
	}
	if _, err := ext.Write([]byte{0x12, 0x34}); err != nil {
		t.Fatal(err)
	}
	if _, err := ext.Read(make([]byte, ext.Len()-1)); err != io.ErrShortBuffer {
		t.Fatalf("short buffer: %v", err)
	}
	got := make([]byte, ext.Len())
	n, err := ext.Read(got)
	if err != io.EOF || n != len(got) || !bytes.Equal(got, []byte{0x12, 0xe0, 0, 2, 0x12, 0x34}) {
		t.Fatalf("server padding encoding: %x, %d, %v", got, n, err)
	}
}
